package main

import "testing"

func TestAdd(t *testing.T) {
	tests := []struct {
		name string
		a    int
		b    int
		want int
	}{
		{"two plus three", 2, 3, 5},
		{"zero plus zero", 0, 0, 0},
		{"negative values", -1, -2, -3},
		{"large positive values", 1000000000, 1000000000, 2000000000},
		{"large negative values", -1000000000, -1000000000, -2000000000},
		{"max int boundary", 2147483647, 0, 2147483647},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := add(tt.a, tt.b); got != tt.want {
				t.Fatalf("add(%d, %d) = %d, want %d", tt.a, tt.b, got, tt.want)
			}
		})
	}
}

